        e[4] = tmp;
        tmp = e[2];
        e[2] = e[8];
        e[8] = tmp;
        tmp = e[3];
        e[3] = e[12];
        e[12] = tmp;
        tmp = e[6];
        e[6] = e[9];
        e[9] = tmp;
        tmp = e[7];
        e[7] = e[13];
        e[13] = tmp;
        tmp = e[11];
        e[11] = e[14];
        e[14] = tmp;
        return this;
